functions.psbt_write_header:
static enum psbt_result psbt_write_header(struct psbt *tx)
{
    if (tx->write_pos + (sizeof(PSBT_MAGIC)) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "43";
        return PSBT_OOB_WRITE;
    };
    memcpy(tx->write_pos, PSBT_MAGIC, sizeof(PSBT_MAGIC));
    tx->write_pos += sizeof(PSBT_MAGIC);
    if (tx->write_pos + (1) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "47";
        return PSBT_OOB_WRITE;
    };
    *tx->write_pos = 0xff;
    tx->write_pos++;
    tx->state = PSBT_ST_GLOBAL;
    return PSBT_OK;
}

functions.psbt_init:
enum psbt_result psbt_init(struct psbt *tx, unsigned char *dest, size_t dest_size)
{
    tx->write_pos = dest;
    tx->data = dest;
    tx->data_capacity = dest_size;
    tx->state = PSBT_ST_INIT;
    return PSBT_OK;
}

functions.psbt_close_records:
enum psbt_result psbt_close_records(struct psbt *tx)
{
    if (tx->write_pos + (1) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "76";
        return PSBT_OOB_WRITE;
    };
    *tx->write_pos = '\0';
    tx->write_pos++;
    return PSBT_OK;
}

functions.psbt_finalize:
enum psbt_result psbt_finalize(struct psbt *tx)
{
    enum psbt_result res;
    if (tx->state != PSBT_ST_OUTPUTS_NEW && tx->state != PSBT_ST_OUTPUTS)
    {
        psbt_errmsg = "psbt_finalize: no output records found";
        return PSBT_INVALID_STATE;
    }
    res = psbt_close_records(tx);
    if (res != PSBT_OK)
        return res;
    tx->state = PSBT_ST_FINALIZED;
    return PSBT_OK;
}

functions.psbt_write_record:
static enum psbt_result psbt_write_record(struct psbt *tx, struct psbt_record *rec)
{
    u32 size;
    u32 key_size_with_type = rec->key_size + 1;
    size = compactsize_length(key_size_with_type);
    if (tx->write_pos + (size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "108";
        return PSBT_OOB_WRITE;
    };
    compactsize_write((u8 *)tx->write_pos, key_size_with_type);
    tx->write_pos += size;
    if (tx->write_pos + (1) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "113";
        return PSBT_OOB_WRITE;
    };
    *tx->write_pos++ = rec->type;
    if (tx->write_pos + (rec->key_size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "117";
        return PSBT_OOB_WRITE;
    };
    memcpy(tx->write_pos, rec->key, rec->key_size);
    tx->write_pos += rec->key_size;
    size = compactsize_length(rec->val_size);
    if (tx->write_pos + (size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "123";
        return PSBT_OOB_WRITE;
    };
    compactsize_write((u8 *)tx->write_pos, rec->val_size);
    tx->write_pos += size;
    if (tx->write_pos + (rec->val_size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "128";
        return PSBT_OOB_WRITE;
    };
    memcpy(tx->write_pos, rec->val, rec->val_size);
    tx->write_pos += rec->val_size;
    return PSBT_OK;
}

functions.psbt_read_header:
static enum psbt_result psbt_read_header(struct psbt *tx)
{
    if (tx->write_pos + (4) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "137";
        return PSBT_OOB_WRITE;
    };
    ;
    if (memcmp(tx->write_pos, PSBT_MAGIC, sizeof(PSBT_MAGIC)) != 0)
    {
        psbt_errmsg = "psbt_read: invalid magic header";
        return PSBT_READ_ERROR;
    }
    tx->write_pos += 4;
    if (*tx->write_pos++ != 0xff)
    {
        psbt_errmsg = "psbt_read: no 0xff found after magic";
        return PSBT_READ_ERROR;
    }
    tx->state = PSBT_ST_GLOBAL;
    return PSBT_OK;
}

