functions.psbt_read_record:
static enum psbt_result psbt_read_record(struct psbt *tx, size_t src_size, struct psbt_record *rec)
{
    enum psbt_result res = PSBT_OK;
    u64 size;
    u32 size_len;
    size_len = compactsize_peek_length(*tx->write_pos);
    if (tx->write_pos + (size_len) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "271";
        return PSBT_OOB_WRITE;
    };
    size = compactsize_read(tx->write_pos, &res);
    ((size > 0) ? (void)(0) : __assert_fail("size > 0", "psbt.c", 273, __extension__ __PRETTY_FUNCTION__));
    tx->write_pos += size_len;
    ;
    if (res != PSBT_OK)
        return res;
    if (tx->write_pos + size > tx->data + src_size)
    {
        psbt_errmsg = "psbt_read: record key size too large";
        return PSBT_READ_ERROR;
    }
    if (tx->write_pos + (size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "288";
        return PSBT_OOB_WRITE;
    };
    rec->key_size = size - 1;
    rec->type = *tx->write_pos;
    rec->key = tx->write_pos + 1;
    tx->write_pos += size;
    ;
    ;
    switch (tx->state)
    {
    case PSBT_ST_GLOBAL:
        rec->scope = PSBT_SCOPE_GLOBAL;
        break;
    case PSBT_ST_INPUTS:
        rec->scope = PSBT_SCOPE_INPUTS;
        break;
    case PSBT_ST_OUTPUTS:
        rec->scope = PSBT_SCOPE_OUTPUTS;
        break;
    default:
        psbt_errmsg = "psbt_read_record: invalid record state";
        return PSBT_INVALID_STATE;
    }
    size_len = compactsize_peek_length(*tx->write_pos);
    if (tx->write_pos + (size_len) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "321";
        return PSBT_OOB_WRITE;
    };
    size = compactsize_read(tx->write_pos, &res);
    if (res != PSBT_OK)
        return res;
    tx->write_pos += size_len;
    if (tx->write_pos + size > tx->data + src_size)
    {
        psbt_errmsg = "psbt_read: record value size too large";
        return PSBT_READ_ERROR;
    }
    rec->val_size = size;
    rec->val = tx->write_pos;
    if (tx->write_pos + (size) > tx->data + tx->data_capacity)
    {
        psbt_errmsg = "write out of bounds "
                      "psbt.c"
                      ":"
                      "337";
        return PSBT_OOB_WRITE;
    };
    tx->write_pos += size;
    return PSBT_OK;
}

functions.tx_counter:
static void tx_counter(struct psbt_txelem *elem)
{
    struct psbt_elem psbt_elem;
    struct psbt_tx_counter *counter = (struct psbt_tx_counter *)elem->user_data;
    psbt_elem.user_data = counter->user_data;
    psbt_elem.type = PSBT_ELEM_TXELEM;
    psbt_elem.elem.txelem = elem;
    if (counter->handler)
        counter->handler(&psbt_elem);
    switch (elem->elem_type)
    {
    case PSBT_TXELEM_TXIN:
        counter->inputs++;
        return;
    case PSBT_TXELEM_TXOUT:
        counter->outputs++;
        return;
    default:
        return;
    }
}

functions.psbt_read:
enum psbt_result psbt_read(const unsigned char *src, size_t src_size, struct psbt *tx, psbt_elem_handler *elem_handler,
                           void *user_data)
{
    struct psbt_record rec;
    enum psbt_result res;
    struct psbt_elem elem;
    elem.type = PSBT_ELEM_RECORD;
    elem.user_data = user_data;
    int kvs = 0;
    u8 *end;
    struct psbt_tx_counter counter = {
        .inputs = 0,
        .outputs = 0,
        .user_data = user_data,
        .handler = elem_handler,
    };
    if (tx->state != PSBT_ST_INIT)
    {
        psbt_errmsg = "psbt_read: psbt not initialized, use psbt_init first";
        return PSBT_INVALID_STATE;
    }
    if (src_size > tx->data_capacity)
    {
        psbt_errmsg = "psbt_read: read buffer is larger than psbt capacity";
        return PSBT_OOB_WRITE;
    }
    if (src != tx->data)
        memcpy(tx->data, src, src_size);
    tx->state = PSBT_ST_INIT;
    tx->write_pos = tx->data;
    tx->data_capacity = src_size;
    end = tx->data + src_size;
    while (tx->state != PSBT_ST_FINALIZED && tx->write_pos <= end)
    {
        switch (tx->state)
        {
        case PSBT_ST_INIT:;
            res = psbt_read_header(tx);
            if (res != PSBT_OK)
                return res;
            break;
        case PSBT_ST_GLOBAL:
        case PSBT_ST_INPUTS:
        case PSBT_ST_OUTPUTS:
            if (*tx->write_pos == 0)
            {
                switch (tx->state)
                {
                case PSBT_ST_GLOBAL:
                    tx->state = PSBT_ST_INPUTS_NEW;
                    break;
                case PSBT_ST_INPUTS:
                    if (++kvs >= counter.inputs)
                    {
                        tx->state = PSBT_ST_OUTPUTS_NEW;
                        kvs = 0;
                    }
                    else
                        tx->state = PSBT_ST_INPUTS_NEW;
                    break;
                case PSBT_ST_OUTPUTS:
                    if (++kvs >= counter.outputs)
                        tx->state = PSBT_ST_FINALIZED;
                    else
                        tx->state = PSBT_ST_OUTPUTS_NEW;
                    break;
                default:
                    ((!"psbt_read: invalid state at null byte")
                         ? (void)(0)
                         : __assert_fail("!\"psbt_read: invalid state at null byte\"", "psbt.c", 454,
                                         __extension__ __PRETTY_FUNCTION__));
                }
            }
            else
            {
                ;
                res = psbt_read_record(tx, src_size, &rec);
                if (res != PSBT_OK)
                    return res;
                if (tx->state == PSBT_ST_GLOBAL && rec.type == PSBT_GLOBAL_UNSIGNED_TX)
                {
                    res = psbt_btc_tx_parse(rec.val, rec.val_size, (void *)&counter, tx_counter);
                    if (res != PSBT_OK)
                        return res;
                }
                if (elem_handler)
                {
                    elem.type = PSBT_ELEM_RECORD;
                    elem.index = kvs;
                    elem.elem.rec = &rec;
                    elem_handler(&elem);
                }
            }
            break;
        case PSBT_ST_OUTPUTS_NEW:
            ((*tx->write_pos == 0)
                 ? (void)(0)
                 : __assert_fail("*tx->write_pos == 0", "psbt.c", 489, __extension__ __PRETTY_FUNCTION__));
            tx->write_pos++;
            tx->state = PSBT_ST_OUTPUTS;
            break;
        case PSBT_ST_INPUTS_NEW:
            ((*tx->write_pos == 0)
                 ? (void)(0)
                 : __assert_fail("*tx->write_pos == 0", "psbt.c", 495, __extension__ __PRETTY_FUNCTION__));
            tx->write_pos++;
            tx->state = PSBT_ST_INPUTS;
            break;
        case PSBT_ST_FINALIZED:
            ((!"impossible") ? (void)(0)
                             : __assert_fail("!\"impossible\"", "psbt.c", 501, __extension__ __PRETTY_FUNCTION__));
            break;
        }
    }
    if (tx->state != PSBT_ST_FINALIZED)
    {
        psbt_errmsg = "psbt_read: invalid psbt";
        return PSBT_INVALID_STATE;
    }
    else if (tx->state == PSBT_ST_FINALIZED && *tx->write_pos != 0)
    {
        psbt_errmsg = "psbt_read: expected null byte at end of psbt";
        return PSBT_READ_ERROR;
    }
    tx->write_pos++;
    return PSBT_OK;
}

functions.psbt_write_global_record:
enum psbt_result psbt_write_global_record(struct psbt *tx, struct psbt_record *rec)
{
    if (tx->state == PSBT_ST_INIT)
    {
        psbt_write_header(tx);
        tx->state = PSBT_ST_GLOBAL;
    }
    else if (tx->state != PSBT_ST_GLOBAL)
    {
        psbt_errmsg = "psbt_write_global_record: you can only write a "
                      "global record after psbt_init and before "
                      "psbt_write_input_record";
        return PSBT_INVALID_STATE;
    }
    return psbt_write_record(tx, rec);
}

functions.psbt_new_input_record_set:
enum psbt_result psbt_new_input_record_set(struct psbt *tx)
{
    enum psbt_result res;
    if (tx->state == PSBT_ST_GLOBAL || tx->state == PSBT_ST_INPUTS_NEW || tx->state == PSBT_ST_INPUTS)
    {
        res = psbt_close_records(tx);
        if (res != PSBT_OK)
            return res;
        tx->state = PSBT_ST_INPUTS_NEW;
        return PSBT_OK;
    }
    else if (tx->state != PSBT_ST_INPUTS)
    {
        psbt_errmsg = "psbt_new_input_record_set: "
                      "this can only be called after psbt_write_global_record, "
                      "psbt_new_input_record_set, "
                      "or psbt_write_input_record";
        return PSBT_INVALID_STATE;
    }
    return psbt_close_records(tx);
}

functions.psbt_new_output_record_set:
enum psbt_result psbt_new_output_record_set(struct psbt *tx)
{
    enum psbt_result res;
    if (tx->state == PSBT_ST_INPUTS || tx->state == PSBT_ST_INPUTS_NEW || tx->state == PSBT_ST_OUTPUTS_NEW ||
        tx->state == PSBT_ST_OUTPUTS)
    {
        res = psbt_close_records(tx);
        if (res != PSBT_OK)
            return res;
        tx->state = PSBT_ST_OUTPUTS_NEW;
        return PSBT_OK;
    }
    else if (tx->state != PSBT_ST_OUTPUTS)
    {
        psbt_errmsg = "psbt_new_output_record_set: "
                      "this can only be called after writing input records";
        return PSBT_INVALID_STATE;
    }
    return psbt_close_records(tx);
}

functions.psbt_print:
enum psbt_result psbt_print(struct psbt *tx, FILE *stream)
{
    if (tx->state != PSBT_ST_FINALIZED)
    {
        psbt_errmsg = "psbt_print: transaction is not finished";
        return PSBT_INVALID_STATE;
    }
    size_t size = psbt_size(tx);
    for (size_t i = 0; i < size; ++i)
        fprintf(stream, "%02x", tx->data[i]);
    printf("\n");
    return PSBT_OK;
}

functions.psbt_write_input_record:
enum psbt_result psbt_write_input_record(struct psbt *tx, struct psbt_record *rec)
{
    enum psbt_result res;
    if (tx->state == PSBT_ST_GLOBAL)
    {
        if ((res = psbt_close_records(tx)) != PSBT_OK)
            return res;
        tx->state = PSBT_ST_INPUTS;
    }
    else if (tx->state != PSBT_ST_INPUTS && tx->state != PSBT_ST_INPUTS_NEW)
    {
        psbt_errmsg = "psbt_write_input_record: attempting to write an "
                      "input record before any global records have been written."
                      " use psbt_write_global_record first";
        return PSBT_INVALID_STATE;
    }
    return psbt_write_record(tx, rec);
}

functions.psbt_write_output_record:
enum psbt_result psbt_write_output_record(struct psbt *tx, struct psbt_record *rec)
{
    enum psbt_result res;
    if (tx->state == PSBT_ST_INPUTS)
    {
        if ((res = psbt_close_records(tx)) != PSBT_OK)
            return res;
        tx->state = PSBT_ST_OUTPUTS;
    }
    else if (tx->state != PSBT_ST_OUTPUTS && tx->state != PSBT_ST_OUTPUTS_NEW)
    {
        psbt_errmsg = "psbt_write_input_record: attempting to write an "
                      "input record before any global records have been written."
                      " use psbt_write_global_record first";
        return PSBT_INVALID_STATE;
    }
    return psbt_write_record(tx, rec);
}

functions.hexdigit:
static inline u8 hexdigit(char hex)
{
    return (hex <= '9') ? hex - '0'
                        : (__extension__({
                              int __res;
                              if (sizeof(hex) > 1)
                              {
                                  if (__builtin_constant_p(hex))
                                  {
                                      int __c = (hex);
                                      __res = __c < -128 || __c > 255 ? __c : (*__ctype_toupper_loc())[__c];
                                  }
                                  else
                                      __res = toupper(hex);
                              }
                              else
                                  __res = (*__ctype_toupper_loc())[(int)(hex)];
                              __res;
                          })) -
                              'A' + 10;
}

functions.psbt_hex_decode:
enum psbt_result psbt_hex_decode(const char *src, size_t src_size, unsigned char *dest, size_t dest_size)
{
    enum psbt_result res = PSBT_OK;
    if (src_size % 2 != 0)
    {
        psbt_errmsg = "psbt_decode: invalid hex string";
        return PSBT_READ_ERROR;
    }
    if (dest_size < src_size / 2)
    {
        psbt_errmsg = "psbt_decode: dest_size must be at least half the"
                      " size of src_size";
        return PSBT_READ_ERROR;
    }
    if (res != PSBT_OK)
        return res;
    for (size_t i = 0; i < src_size; i += 2)
    {
        u8 c1 = src[i];
        u8 c2 = src[i + 1];
