    }
    if (p + (4) > data + data_size)
    {
        psbt_errmsg = "out of bounds "
                      "tx.c"
                      ":"
                      "233";
        return PSBT_READ_ERROR;
    };
    tx.lock_time = parse_le32(p);
    p += 4;
    if (p != data + data_size)
    {
        psbt_errmsg = "psbt_btc_tx_parse: parsing fell short";
        return PSBT_READ_ERROR;
    }
    txelem.elem_type = PSBT_TXELEM_TX;
    txelem.elem.tx = &tx;
    handler(&txelem);
    return PSBT_OK;
}
